/*
 * main.c - Test Runner for DeepSeekV3 MoE C Implementation
 *
 * Week 7: Communication - Pure C Implementation
 *
 * Loads test cases generated by Python scripts, runs the C implementation,
 * and compares outputs with expected values from PyTorch.
 *
 * Usage: ./moe_test [test_cases_dir]
 *   Default test_cases_dir: ./test_cases
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "moe_operator.h"
#include "matrix_ops.h"
#include "activations.h"
#include "test_loader.h"

#define TOLERANCE 1e-4f

static int total_tests = 0;
static int passed_tests = 0;

/* ============================================================
 * Test: DeepseekV3MLP
 * ============================================================ */
static void test_mlp(const char *filepath) {
    char *json = read_file(filepath);
    if (!json) return;

    char *test_name = json_get_string(json, "test_name");
    int hidden_size = json_get_int(json, "hidden_size");
    int intermediate_size = json_get_int(json, "intermediate_size");
    int batch_size = json_get_int(json, "batch_size");
    int seq_len = json_get_int(json, "seq_len");
    int num_tokens = batch_size * seq_len;

    /* Load weights */
    int cnt;
    float *gate_proj_w = json_get_float_array(json, "gate_proj_weight", &cnt);
    float *up_proj_w   = json_get_float_array(json, "up_proj_weight", &cnt);
    float *down_proj_w = json_get_float_array(json, "down_proj_weight", &cnt);
    float *input       = json_get_float_array(json, "input", &cnt);
    float *expected     = json_get_float_array(json, "expected_output", &cnt);

    /* Run C implementation */
    float *output = alloc_floats(num_tokens * hidden_size);
    deepseek_mlp_forward(input, gate_proj_w, up_proj_w, down_proj_w,
                          output, num_tokens, hidden_size, intermediate_size);

    /* Compare */
    TestResult result = compare_outputs(test_name ? test_name : filepath,
                                         expected, output,
                                         num_tokens * hidden_size, TOLERANCE);
    print_test_result(&result, TOLERANCE);

    total_tests++;
    if (result.passed) passed_tests++;

    /* Cleanup */
    free(gate_proj_w); free(up_proj_w); free(down_proj_w);
    free(input); free(expected); free(output);
    if (test_name) free(test_name);
    free(json);
}


/* ============================================================
 * Test: DeepseekV3TopkRouter
 * ============================================================ */
static void test_router(const char *filepath) {
    char *json = read_file(filepath);
    if (!json) return;

    char *test_name = json_get_string(json, "test_name");
    int hidden_size = json_get_int(json, "hidden_size");
    int n_routed_experts = json_get_int(json, "n_routed_experts");
    int batch_size = json_get_int(json, "batch_size");
    int seq_len = json_get_int(json, "seq_len");
    int num_tokens = batch_size * seq_len;

    int cnt;
    float *router_weight = json_get_float_array(json, "router_weight", &cnt);
    float *input         = json_get_float_array(json, "input", &cnt);
    float *expected       = json_get_float_array(json, "expected_output", &cnt);

    /* Flatten input from (batch, seq, hidden) to (num_tokens, hidden) */
    float *output = alloc_floats(num_tokens * n_routed_experts);
    deepseek_router_forward(input, router_weight, output,
                             num_tokens, hidden_size, n_routed_experts);

    TestResult result = compare_outputs(test_name ? test_name : filepath,
                                         expected, output,
                                         num_tokens * n_routed_experts, TOLERANCE);
    print_test_result(&result, TOLERANCE);

    total_tests++;
    if (result.passed) passed_tests++;

    free(router_weight); free(input); free(expected); free(output);
    if (test_name) free(test_name);
    free(json);
}


/* ============================================================
 * Test: DeepseekV3NaiveMoe (Experts)
 * ============================================================ */
static void test_experts(const char *filepath) {
    char *json = read_file(filepath);
    if (!json) return;

    char *test_name = json_get_string(json, "test_name");
    int num_experts = json_get_int(json, "num_experts");
    int hidden_dim = json_get_int(json, "hidden_dim");
    int intermediate_dim = json_get_int(json, "intermediate_dim");
    int num_tokens = json_get_int(json, "num_tokens");
    int top_k = json_get_int(json, "top_k");

    int cnt;
    float *gate_up_proj  = json_get_float_array(json, "gate_up_proj", &cnt);
    float *down_proj     = json_get_float_array(json, "down_proj", &cnt);
    float *hidden_states = json_get_float_array(json, "hidden_states", &cnt);
    int   *top_k_index   = json_get_int_array(json, "top_k_index", &cnt);
    float *top_k_weights = json_get_float_array(json, "top_k_weights", &cnt);
    float *expected       = json_get_float_array(json, "expected_output", &cnt);

    float *output = alloc_floats(num_tokens * hidden_dim);
    deepseek_naive_moe_forward(hidden_states, top_k_index, top_k_weights,
                                gate_up_proj, down_proj, output,
                                num_tokens, hidden_dim, intermediate_dim,
                                num_experts, top_k);

    TestResult result = compare_outputs(test_name ? test_name : filepath,
                                         expected, output,
                                         num_tokens * hidden_dim, TOLERANCE);
    print_test_result(&result, TOLERANCE);

    total_tests++;
    if (result.passed) passed_tests++;

    free(gate_up_proj); free(down_proj); free(hidden_states);
    free(top_k_index); free(top_k_weights); free(expected); free(output);
    if (test_name) free(test_name);
    free(json);
}


/* ============================================================
 * Test: Full DeepseekV3MoE
 * ============================================================
 *
 * The full MoE test is more complex because the routing is
 * non-trivial. We compare:
 *   1. Router logits (should match exactly)
 *   2. Final output (routing may differ in tie-breaking,
 *      but with small test cases should match)
 */
static void test_moe_full(const char *filepath) {
    char *json = read_file(filepath);
    if (!json) return;

    char *test_name = json_get_string(json, "test_name");
    int hidden_size = json_get_int(json, "hidden_size");
    int moe_intermediate_size = json_get_int(json, "moe_intermediate_size");
    int n_routed_experts = json_get_int(json, "n_routed_experts");
    int n_shared_experts = json_get_int(json, "n_shared_experts");
    int n_group = json_get_int(json, "n_group");
    int topk_group = json_get_int(json, "topk_group");
    int top_k = json_get_int(json, "top_k");
    int norm_topk_prob = json_get_bool(json, "norm_topk_prob");
    float routed_scaling_factor = json_get_float(json, "routed_scaling_factor");
    int batch_size = json_get_int(json, "batch_size");
    int seq_len = json_get_int(json, "seq_len");
    int num_tokens = batch_size * seq_len;
    (void)n_shared_experts; /* used only via weights */

    int cnt;
    /* Load all weights */
    float *router_weight    = json_get_float_array(json, "router_weight", &cnt);
    float *e_score_bias     = json_get_float_array(json, "e_score_correction_bias", &cnt);
    float *expert_gate_up   = json_get_float_array(json, "expert_gate_up_proj", &cnt);
    float *expert_down      = json_get_float_array(json, "expert_down_proj", &cnt);
    float *shared_gate_w    = json_get_float_array(json, "shared_gate_proj_weight", &cnt);
    float *shared_up_w      = json_get_float_array(json, "shared_up_proj_weight", &cnt);
    float *shared_down_w    = json_get_float_array(json, "shared_down_proj_weight", &cnt);
    float *input            = json_get_float_array(json, "input", &cnt);

    /* Load expected outputs */
    float *expected_output  = json_get_float_array(json, "expected_output", &cnt);
    float *expected_logits  = json_get_float_array(json, "router_logits", &cnt);

    /* Allocate output buffers */
    float *output = alloc_floats(num_tokens * hidden_size);
    float *out_logits = alloc_floats(num_tokens * n_routed_experts);
    int   *out_topk_idx = (int *)malloc(num_tokens * top_k * sizeof(int));
    float *out_topk_w = alloc_floats(num_tokens * top_k);

    /* Run full MoE */
    deepseek_moe_forward(
        input, router_weight, e_score_bias,
        expert_gate_up, expert_down,
        shared_gate_w, shared_up_w, shared_down_w,
        output, out_logits, out_topk_idx, out_topk_w,
        num_tokens, hidden_size, moe_intermediate_size,
        n_routed_experts, n_shared_experts,
        n_group, topk_group, top_k,
        norm_topk_prob, routed_scaling_factor
    );

    /* Compare router logits first */
    char logits_name[256];
    snprintf(logits_name, sizeof(logits_name), "%s (router_logits)",
             test_name ? test_name : filepath);
    TestResult logits_result = compare_outputs(logits_name,
                                                expected_logits, out_logits,
                                                num_tokens * n_routed_experts, TOLERANCE);
    print_test_result(&logits_result, TOLERANCE);
    total_tests++;
    if (logits_result.passed) passed_tests++;

    /* Compare final output */
    char output_name[256];
    snprintf(output_name, sizeof(output_name), "%s (final_output)",
             test_name ? test_name : filepath);
    TestResult output_result = compare_outputs(output_name,
                                                expected_output, output,
                                                num_tokens * hidden_size, TOLERANCE);
    print_test_result(&output_result, TOLERANCE);
    total_tests++;
    if (output_result.passed) passed_tests++;

    /* Cleanup */
    free(router_weight); free(e_score_bias);
    free(expert_gate_up); free(expert_down);
    free(shared_gate_w); free(shared_up_w); free(shared_down_w);
    free(input); free(expected_output); free(expected_logits);
    free(output); free(out_logits); free(out_topk_idx); free(out_topk_w);
    if (test_name) free(test_name);
    free(json);
}


/* ============================================================
 * Main
 * ============================================================ */
int main(int argc, char *argv[]) {
    const char *test_dir = (argc > 1) ? argv[1] : "./test_cases";

    printf("============================================================\n");
    printf("DeepSeekV3 MoE Operator - C Implementation Test Runner\n");
    printf("============================================================\n");
    printf("Test directory: %s\n", test_dir);
    printf("Tolerance: %.0e\n", TOLERANCE);
    printf("============================================================\n");

    char path[512];

    /* --- MLP Tests --- */
    printf("\n--- Block 1: DeepseekV3MLP ---\n");
    snprintf(path, sizeof(path), "%s/mlp_test_1.json", test_dir);
    test_mlp(path);
    snprintf(path, sizeof(path), "%s/mlp_test_2.json", test_dir);
    test_mlp(path);
    snprintf(path, sizeof(path), "%s/mlp_test_3.json", test_dir);
    test_mlp(path);

    /* --- Router Tests --- */
    printf("\n--- Block 2: DeepseekV3TopkRouter ---\n");
    snprintf(path, sizeof(path), "%s/router_test_1.json", test_dir);
    test_router(path);
    snprintf(path, sizeof(path), "%s/router_test_2.json", test_dir);
    test_router(path);
    snprintf(path, sizeof(path), "%s/router_test_3.json", test_dir);
    test_router(path);

    /* --- Expert Tests --- */
    printf("\n--- Block 3: DeepseekV3NaiveMoe (Experts) ---\n");
    snprintf(path, sizeof(path), "%s/experts_test_1.json", test_dir);
    test_experts(path);
    snprintf(path, sizeof(path), "%s/experts_test_2.json", test_dir);
    test_experts(path);
    snprintf(path, sizeof(path), "%s/experts_test_3.json", test_dir);
    test_experts(path);

    /* --- Full MoE Tests --- */
    printf("\n--- Block 4: DeepseekV3MoE (Full) ---\n");
    snprintf(path, sizeof(path), "%s/moe_full_test_1.json", test_dir);
    test_moe_full(path);
    snprintf(path, sizeof(path), "%s/moe_full_test_2.json", test_dir);
    test_moe_full(path);
    snprintf(path, sizeof(path), "%s/moe_full_test_3.json", test_dir);
    test_moe_full(path);

    /* --- Summary --- */
    printf("\n============================================================\n");
    printf("RESULTS: %d / %d tests passed\n", passed_tests, total_tests);
    printf("============================================================\n");

    return (passed_tests == total_tests) ? 0 : 1;
}
